import React, { useState } from 'react';
import './SongsPage.css';

function SongsPage({ onSongSelect, currentSong, onPlaylistUpdate, onNavigateToHome }) {
  const [songs] = useState([
    { id: 1, title: 'Shape of You', artist: 'Ed Sheeran', file: '/songs/Shape of You.mp3', cover: '/covers/SoY Cover.jpeg', duration: '03:52' },
    { id: 2, title: 'Despacito', artist: 'Luis Fonsi (ft.Daddy Yankee)', file: '/songs/Despacito.mp3', cover: '/covers/Despacito Cover.jpeg', duration: '04:40' },
    { id: 3, title: 'See You Again', artist: 'Wiz Khalifa (ft.Charlie Puth)', file: '/songs/See You Again.mp3', cover: '/covers/SYA Cover.jpeg', duration: '03:57' },
    { id: 4, title: 'Roar', artist: 'Katy Perry', file: '/songs/Roar.mp3', cover: '/covers/Roar Cover.jpeg', duration: '03:50' },
    { id: 5, title: 'Sorry', artist: 'Justin Bieber', file: '/songs/Sorry.mp3', cover: '/covers/Sorry Cover.jpeg', duration: '03:18' },
    { id: 6, title: 'Waka Waka', artist: 'Shakira', file: '/songs/Waka Waka.mp3', cover: '/covers/Waka Waka Cover.jpeg', duration: '03:30' },
    { id: 7, title: 'Perfect', artist: 'Ed Sheeran', file: '/songs/Perfect.mp3', cover: '/covers/Perfect Cover.jpeg', duration: '04:20' },
    { id: 8, title: 'Sugar', artist: 'Maroon 5', file: '/songs/Sugar.mp3', cover: '/covers/Sugar Cover.jpeg', duration: '03:51' },
    { id: 9, title: 'We Don\'t Talk Anymore', artist: 'Charlie Puth (ft.Selena Gomez)', file: '/songs/We Don\'t Talk Anymore.mp3', cover: '/covers/WDTA Cover.jpeg', duration: '03:38' },
    { id: 10, title: 'One Love', artist: 'Blue', file: '/songs/One Love.mp3', cover: '/covers/One Love Cover.jpeg', duration: '03:30' }
  ]);

  React.useEffect(() => {
    if (onPlaylistUpdate) {
      onPlaylistUpdate(songs);
    }
  }, [songs, onPlaylistUpdate]);

  const handleSongClick = (song) => {
    onSongSelect(song);
  };

  return (
    <div className="songs-page">
      <div className="songs-header">
        <button className="back-button" onClick={onNavigateToHome}>
          ← Back to Home
        </button>
        <h2>My Collection - Global Hits</h2>
      </div>
      <div className="songs-grid">
        {songs.map((song) => (
          <div
            key={song.id}
            className={`song-card ${currentSong?.id === song.id ? 'active' : ''}`}
            onClick={() => handleSongClick(song)}
          >
            <img src={song.cover} alt={song.title} className="song-cover" />
            <div className="song-info">
              <h3>{song.title}</h3>
              <p>{song.artist}</p>
              <span className="duration">{song.duration}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default SongsPage;
